const schemaData = {
  "tables": [
    {
      "name": "REGIONS",
      "comment": "Regions such as Europe, Asia, Americas.",
      "approx_rows": 4,
      "columns": [
        { "name": "REGION_ID", "data_type": "NUMBER", "nullable": false, "default": null, "comment": "Primary key of regions table" },
        { "name": "REGION_NAME", "data_type": "VARCHAR2(25)", "nullable": true, "default": null, "comment": null }
      ],
      "constraints": [
        { "name": "REG_ID_PK", "type": "PRIMARY KEY", "columns": [ "REGION_ID" ] }
      ],
      "indexes": [
        { "name": "REG_ID_PK", "columns": [ "REGION_ID" ], "unique": true, "note": "system index for PK" }
      ],
      "storage": "heap"
    },
    {
      "name": "COUNTRIES",
      "comment": "Country table. References regions table.",
      "approx_rows": 25,
      "columns": [
        { "name": "COUNTRY_ID", "data_type": "CHAR(2)", "nullable": false, "default": null, "comment": "Primary key of countries table" },
        { "name": "COUNTRY_NAME", "data_type": "VARCHAR2(40)", "nullable": true, "default": null, "comment": null },
        { "name": "REGION_ID", "data_type": "NUMBER", "nullable": true, "default": null, "comment": "Region where country is located" }
      ],
      "constraints": [
        { "name": "COUNTRY_C_ID_PK", "type": "PRIMARY KEY", "columns": [ "COUNTRY_ID" ] },
        { "name": "COUNTR_REG_FK", "type": "FOREIGN KEY", "columns": [ "REGION_ID" ], "references": "REGIONS(REGION_ID)" }
      ],
      "indexes": [
        { "name": "COUNTRY_C_ID_PK", "columns": [ "COUNTRY_ID" ], "unique": true }
      ],
      "storage": "index-organized table (ORGANIZATION INDEX)"
    },
    {
      "name": "LOCATIONS",
      "comment": "Office, warehouse and production-site addresses.",
      "approx_rows": 23,
      "columns": [
        { "name": "LOCATION_ID", "data_type": "NUMBER(4)", "nullable": false, "default": null, "comment": "Primary key of locations table" },
        { "name": "STREET_ADDRESS", "data_type": "VARCHAR2(40)", "nullable": true, "default": null, "comment": null },
        { "name": "POSTAL_CODE", "data_type": "VARCHAR2(12)", "nullable": true, "default": null, "comment": null },
        { "name": "CITY", "data_type": "VARCHAR2(30)", "nullable": false, "default": null, "comment": null },
        { "name": "STATE_PROVINCE", "data_type": "VARCHAR2(25)", "nullable": true, "default": null, "comment": null },
        { "name": "COUNTRY_ID", "data_type": "CHAR(2)", "nullable": true, "default": null, "comment": "Country where the location is" }
      ],
      "constraints": [
        { "name": "LOC_ID_PK", "type": "PRIMARY KEY", "columns": [ "LOCATION_ID" ] },
        { "name": "LOC_C_ID_FK", "type": "FOREIGN KEY", "columns": [ "COUNTRY_ID" ], "references": "COUNTRIES(COUNTRY_ID)" }
      ],
      "indexes": [
        { "name": "LOC_ID_PK", "columns": [ "LOCATION_ID" ], "unique": true },
        { "name": "LOC_CITY_IX", "columns": [ "CITY" ], "unique": false },
        { "name": "LOC_STATE_PROVINCE_IX", "columns": [ "STATE_PROVINCE" ], "unique": false },
        { "name": "LOC_COUNTRY_IX", "columns": [ "COUNTRY_ID" ], "unique": false }
      ],
      "storage": "heap"
    },
    {
      "name": "DEPARTMENTS",
      "comment": "Departments where employees work. References locations and employees (manager).",
      "approx_rows": 27,
      "columns": [
        { "name": "DEPARTMENT_ID", "data_type": "NUMBER(4)", "nullable": false, "default": null, "comment": "Primary key of departments table" },
        { "name": "DEPARTMENT_NAME", "data_type": "VARCHAR2(30)", "nullable": false, "default": null, "comment": null },
        { "name": "MANAGER_ID", "data_type": "NUMBER(6)", "nullable": true, "default": null, "comment": "Manager of the department (employee id)" },
        { "name": "LOCATION_ID", "data_type": "NUMBER(4)", "nullable": true, "default": null, "comment": "Location id where the department is located" }
      ],
      "constraints": [
        { "name": "DEPT_ID_PK", "type": "PRIMARY KEY", "columns": [ "DEPARTMENT_ID" ] },
        { "name": "DEPT_LOC_FK", "type": "FOREIGN KEY", "columns": [ "LOCATION_ID" ], "references": "LOCATIONS(LOCATION_ID)" },
        { "name": "DEPT_MGR_FK", "type": "FOREIGN KEY", "columns": [ "MANAGER_ID" ], "references": "EMPLOYEES(EMPLOYEE_ID)", "note": "added via ALTER TABLE after EMPLOYEES is created (circular dependency)" }
      ],
      "indexes": [
        { "name": "DEPT_ID_PK", "columns": [ "DEPARTMENT_ID" ], "unique": true },
        { "name": "DEPT_LOCATION_IX", "columns": [ "LOCATION_ID" ], "unique": false }
      ],
      "storage": "heap"
    },
    {
      "name": "JOBS",
      "comment": "Jobs that employees can hold, with salary ranges.",
      "approx_rows": 19,
      "columns": [
        { "name": "JOB_ID", "data_type": "VARCHAR2(10)", "nullable": false, "default": null, "comment": "Primary key of jobs table" },
        { "name": "JOB_TITLE", "data_type": "VARCHAR2(35)", "nullable": false, "default": null, "comment": null },
        { "name": "MIN_SALARY", "data_type": "NUMBER(6)", "nullable": true, "default": null, "comment": null },
        { "name": "MAX_SALARY", "data_type": "NUMBER(6)", "nullable": true, "default": null, "comment": null }
      ],
      "constraints": [
        { "name": "JOB_ID_PK", "type": "PRIMARY KEY", "columns": [ "JOB_ID" ] }
      ],
      "indexes": [
        { "name": "JOB_ID_PK", "columns": [ "JOB_ID" ], "unique": true }
      ],
      "storage": "heap"
    },
    {
      "name": "EMPLOYEES",
      "comment": "Employee details. References departments, jobs and itself (manager).",
      "approx_rows": 107,
      "columns": [
        { "name": "EMPLOYEE_ID", "data_type": "NUMBER(6)", "nullable": false, "default": null, "comment": "Primary key of employees table" },
        { "name": "FIRST_NAME", "data_type": "VARCHAR2(20)", "nullable": true, "default": null, "comment": null },
        { "name": "LAST_NAME", "data_type": "VARCHAR2(25)", "nullable": false, "default": null, "comment": null },
        { "name": "EMAIL", "data_type": "VARCHAR2(25)", "nullable": false, "default": null, "comment": "Unique" },
        { "name": "PHONE_NUMBER", "data_type": "VARCHAR2(20)", "nullable": true, "default": null, "comment": null },
        { "name": "HIRE_DATE", "data_type": "DATE", "nullable": false, "default": null, "comment": null },
        { "name": "JOB_ID", "data_type": "VARCHAR2(10)", "nullable": false, "default": null, "comment": null },
        { "name": "SALARY", "data_type": "NUMBER(8,2)", "nullable": true, "default": null, "comment": "Must be > 0" },
        { "name": "COMMISSION_PCT", "data_type": "NUMBER(2,2)", "nullable": true, "default": null, "comment": null },
        { "name": "MANAGER_ID", "data_type": "NUMBER(6)", "nullable": true, "default": null, "comment": "Manager's employee id (self reference)" },
        { "name": "DEPARTMENT_ID", "data_type": "NUMBER(4)", "nullable": true, "default": null, "comment": null }
      ],
      "constraints": [
        { "name": "EMP_EMP_ID_PK", "type": "PRIMARY KEY", "columns": [ "EMPLOYEE_ID" ] },
        { "name": "EMP_EMAIL_UK", "type": "UNIQUE", "columns": [ "EMAIL" ] },
        { "name": "EMP_SALARY_MIN", "type": "CHECK", "condition": "salary > 0" },
        { "name": "EMP_DEPT_FK", "type": "FOREIGN KEY", "columns": [ "DEPARTMENT_ID" ], "references": "DEPARTMENTS(DEPARTMENT_ID)" },
        { "name": "EMP_JOB_FK", "type": "FOREIGN KEY", "columns": [ "JOB_ID" ], "references": "JOBS(JOB_ID)" },
        { "name": "EMP_MANAGER_FK", "type": "FOREIGN KEY", "columns": [ "MANAGER_ID" ], "references": "EMPLOYEES(EMPLOYEE_ID)" }
      ],
      "indexes": [
        { "name": "EMP_EMP_ID_PK", "columns": [ "EMPLOYEE_ID" ], "unique": true },
        { "name": "EMP_EMAIL_UK", "columns": [ "EMAIL" ], "unique": true },
        { "name": "EMP_DEPARTMENT_IX", "columns": [ "DEPARTMENT_ID" ], "unique": false },
        { "name": "EMP_JOB_IX", "columns": [ "JOB_ID" ], "unique": false },
        { "name": "EMP_MANAGER_IX", "columns": [ "MANAGER_ID" ], "unique": false },
        { "name": "EMP_NAME_IX", "columns": [ "LAST_NAME", "FIRST_NAME" ], "unique": false }
      ],
      "storage": "heap"
    },
    {
      "name": "JOB_HISTORY",
      "comment": "Employee job history; a row is written when an employee changes job or department.",
      "approx_rows": 10,
      "columns": [
        { "name": "EMPLOYEE_ID", "data_type": "NUMBER(6)", "nullable": false, "default": null, "comment": null },
        { "name": "START_DATE", "data_type": "DATE", "nullable": false, "default": null, "comment": "Must be less than END_DATE" },
        { "name": "END_DATE", "data_type": "DATE", "nullable": false, "default": null, "comment": null },
        { "name": "JOB_ID", "data_type": "VARCHAR2(10)", "nullable": false, "default": null, "comment": null },
        { "name": "DEPARTMENT_ID", "data_type": "NUMBER(4)", "nullable": true, "default": null, "comment": null }
      ],
      "constraints": [
        { "name": "JHIST_EMP_ID_ST_DATE_PK", "type": "PRIMARY KEY", "columns": [ "EMPLOYEE_ID", "START_DATE" ] },
        { "name": "JHIST_DATE_INTERVAL", "type": "CHECK", "condition": "end_date > start_date" },
        { "name": "JHIST_JOB_FK", "type": "FOREIGN KEY", "columns": [ "JOB_ID" ], "references": "JOBS(JOB_ID)" },
        { "name": "JHIST_EMP_FK", "type": "FOREIGN KEY", "columns": [ "EMPLOYEE_ID" ], "references": "EMPLOYEES(EMPLOYEE_ID)" },
        { "name": "JHIST_DEPT_FK", "type": "FOREIGN KEY", "columns": [ "DEPARTMENT_ID" ], "references": "DEPARTMENTS(DEPARTMENT_ID)" }
      ],
      "indexes": [
        { "name": "JHIST_EMP_ID_ST_DATE_PK", "columns": [ "EMPLOYEE_ID", "START_DATE" ], "unique": true },
        { "name": "JHIST_JOB_IX", "columns": [ "JOB_ID" ], "unique": false },
        { "name": "JHIST_EMPLOYEE_IX", "columns": [ "EMPLOYEE_ID" ], "unique": false },
        { "name": "JHIST_DEPARTMENT_IX", "columns": [ "DEPARTMENT_ID" ], "unique": false }
      ],
      "storage": "heap"
    }
  ]
};

return schemaData.tables.map(table => {
  return {
    json: {
      text: `TABLE NAME: ${table.name}\nDESCRIPTION: ${table.comment || 'N/A'}\nSCHEMA DEFINITION:\n${JSON.stringify(table, null, 2)}`,
      metadata: {
        tableName: table.name,
        type: "database_table"
      }
    }
  };
});
